solution_code:
#include <stdio.h>
#include <stddef.h>
#include <stdint.h>

/* Layout (offset: member)
 *  0: tag      (1)  + 3 padding
 *  4: value    (4)
 *  8: flag     (1)  + 7 padding  -> double needs an 8-aligned offset
 * 16: scale    (8)
 * 24: crc      (2)  + 6 tail padding -> size rounded up to 8
 * sizeof = 32
 *
 * Reordered largest-first (double, int32_t, uint16_t, char, char) it is 16 bytes.
 */
struct Frame {
    char     tag;
    int32_t  value;
    char     flag;
    double   scale;
    uint16_t crc;
};

int main(void)
{
    printf("%zu %zu %zu\n",
           sizeof(struct Frame),
           offsetof(struct Frame, scale),
           offsetof(struct Frame, crc));
    return 0;
}

statement_md:
A calibration module keeps its gains both in a plain array and inside a struct. Three helper functions try to change them.

What does this program print?

Assume **x86-64 Linux, gcc, little-endian, `int` = 4 bytes, pointer = 8 bytes**.

```c
#include <stdio.h>

struct Calib {
    int gain;
    int offs[3];
};

static void bump_array(int offs[3])        { offs[0] += 10; }
static void bump_copy(struct Calib c)      { c.gain += 10; c.offs[1] += 10; }
static void bump_ptr(struct Calib *c)      { c->gain += 100; c->offs[2] += 100; }

int main(void)
{
    struct Calib a = { 1, { 2, 3, 4 } };
    struct Calib b;

    bump_array(a.offs);
    bump_copy(a);
    printf("%d %d %d %d\n", a.gain, a.offs[0], a.offs[1], a.offs[2]);

    b = a;
    b.offs[0] = 0;
    bump_ptr(&b);
    printf("%d %d %d\n", a.offs[0], b.gain, b.offs[2]);

    printf("%zu %zu\n", sizeof a, sizeof a.offs);
    return 0;
}
```

