    for (int i = 0; i < n; i++) {
        int e;
        if (scanf("%d", &e) != 1) break;
        struct Timer *t = malloc(sizeof *t);
        if (!t) break;
        t->expiry = e;
        t->id = i + 1;
        t->next = NULL;
        all[made++] = t;
        head = timer_insert(head, t);
    }

    if (head == NULL) {
        printf(made ? "FAIL: list lost\n" : "EMPTY\n");
    } else {
        int count = 0;
        for (struct Timer *p = head; p != NULL && count <= made; p = p->next, count++)
            printf("%s%d#%d", count ? " " : "", p->expiry, p->id);
        printf("\n");
        if (count != made) printf("FAIL: list has %s nodes\n", count > made ? "too many (cycle?)" : "lost");
    }

    for (int i = 0; i < made; i++) free(all[i]);
    free(all);
    return 0;
}

solution_code:
#include <stddef.h>

struct Timer *timer_insert(struct Timer *head, struct Timer *t)
{
    struct Timer **pp = &head;            /* address of the link we may rewrite */

    /* skip every node that must stay in front of t (<= keeps equal keys FIFO) */
    while (*pp != NULL && (*pp)->expiry <= t->expiry)
        pp = &(*pp)->next;

    t->next = *pp;                        /* splice t in front of *pp ... */
    *pp = t;                              /* ... works for head, middle and tail */
    return head;
}

