            sub_show(subs);
        } else if (scanf("%x", &id) == 1) {
            if (strcmp(cmd, "ADD") == 0) {
                sub_add(&subs, (uint16_t)id);
            } else if (strcmp(cmd, "DEL") == 0) {
                int r = sub_remove_all(&subs, (uint16_t)id);   /* FIX: pass &subs */
                printf("DEL 0x%03X removed=%d\n", id, r);
            }
