{
    if (f == NULL)
        return;
    free(f->data);
    free(f);
}

static void freeze(uint32_t dtc)
{
    struct Frame *snap = frame_clone(&live, dtc);
    if (snap == NULL)
        return;
    if (hcount == HIST) {                       /* ring full: drop the oldest */
        frame_destroy(hist[0]);
        memmove(&hist[0], &hist[1], (HIST - 1) * sizeof hist[0]);
        hcount--;
    }
    hist[hcount++] = snap;
}

