                live.data[i] = (uint8_t)b;
            }
            live.len = (uint16_t)n;
        } else if (strcmp(cmd, "FREEZE") == 0) {
            unsigned dtc;
            if (scanf("%x", &dtc) != 1) break;
            freeze(dtc);
        } else if (strcmp(cmd, "DUMP") == 0) {
            dump();
        }
    }

    for (int i = 0; i < hcount; i++)
        frame_destroy(hist[i]);
    free(live.data);
    return 0;
}

