struct TxNode {
    uint32_t       id;
    uint8_t        dlc;
    uint8_t        data[8];
    struct TxNode *next;
};

struct TxQueue {
    struct TxNode *head;
    struct TxNode *tail;
    size_t         count;
};

static int txq_push(struct TxQueue *q, uint32_t id, uint8_t dlc, const uint8_t *data)
{
    struct TxNode *n = malloc(sizeof *n);
    if (n == NULL)
        return -1;
    n->id = id;
    n->dlc = dlc;
    memcpy(n->data, data, sizeof n->data);
    n->next = NULL;
    if (q->tail != NULL)
        q->tail->next = n;
    else
        q->head = n;
    q->tail = n;
    q->count++;
    return 0;
}

static int txq_pop(struct TxQueue *q, struct TxNode *out)
{
    struct TxNode *n = q->head;
    if (n == NULL)
        return -1;
    *out = *n;
    q->head = n->next;
    if (q->head == NULL)
        q->tail = NULL;
    q->count--;
    free(n);
    return 0;
}

/* Remove the oldest pending message with this id. */
static int txq_cancel(struct TxQueue *q, uint32_t id)
{
    struct TxNode *prev = NULL;
    struct TxNode *cur = q->head;
    while (cur != NULL) {
        if (cur->id == id) {
            if (prev != NULL)
                prev->next = cur->next;
            else
                q->head = cur->next;
            q->count--;
            free(cur);
            return 1;
        }
        prev = cur;
        cur = cur->next;
    }
    return 0;
}

static void txq_flush(struct TxQueue *q)
{
    struct TxNode out;
    while (txq_pop(q, &out) == 0)
        ;
}

int main(void)
{
    struct TxQueue q = { NULL, NULL, 0 };
    char cmd[8];

    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "PUSH") == 0) {
            unsigned id, dlc;
            uint8_t data[8] = { 0 };
            if (scanf("%x %u", &id, &dlc) != 2 || dlc > 8) break;
            for (unsigned i = 0; i < dlc; i++) {
                unsigned b;
                if (scanf("%x", &b) != 1) b = 0;
                data[i] = (uint8_t)b;
            }
            txq_push(&q, id, (uint8_t)dlc, data);
        } else if (strcmp(cmd, "POP") == 0) {
            struct TxNode m;
            if (txq_pop(&q, &m) != 0) {
                printf("POP EMPTY\n");
            } else {
                printf("POP 0x%03X [%u]", (unsigned)m.id, (unsigned)m.dlc);
